-- Ruby Sanctum alternatives; existing rankings always take precedence.
local A=ModernWotLKBIS
if not A.compatible then return end
local function Add(id,spec,source)
 local item=A.items[id]
 if item and item.specs[spec] then return end
 if not item then item={specs={}}; A.items[id]=item end
 A.sources[#A.sources+1]=source
 item.specs[spec]={label="ALT 4",conditional=true,sources={#A.sources}}
end
